/* H3 导演台 · 逐步填写独立创作模板库。
   每套模板只收集会真正改变画面的事实，并自动编译为官方 Base 三字段时间轴；
   模板之间的字段、候选、节拍和镜头职责保持隔离，用户仍可逐项修改。 */

export const H3_GUIDED_TEMPLATE_PHASE_KEYS = Object.freeze([
  "scene_time", "start_state", "positions", "objective", "obstacle", "action",
  "framing", "camera", "lighting", "sound", "end_state",
]);

/* H3 原生音频在“少量对白 / 需要时加入对白”这类模糊要求下，可能自行补写
   含混人声或伪语言。逐步填写的全部模板因此统一采用安全默认值：没有用户逐字
   填写的台词清单就只生成环境声和动作音效。需要对白时再由 UI 显式切换模式。 */
const H3_GUIDED_SAFE_DIALOGUE_DEFAULTS = Object.freeze({
  dialogue: "无对白无旁白（纯环境声和动作音效，最稳）",
  dialogue_language: "普通话（简体中文）",
  dialogue_script: "",
  voice_direction: "自然语速、口齿清楚、逐字照读；禁止含混拟声、伪语言、乱码式发音和自动改词",
});

const BASE_PHASE = Object.freeze({
  scene_time: "沿用全局场景、时间和固定空间布局，不新增未填写的地点",
  start_state: "从上一阶段明确留下的角色位置、朝向、动作进度、道具状态、光线方向和摄影机方位开始",
  positions: "角色和主体使用明确的左/中/右、前景/中景/背景位置，朝向和相互距离可见",
  objective: "推进一个观众能够看懂的主要目标",
  obstacle: "只设置一个与主目标直接相关、能够通过可见动作解决的变化或障碍",
  action: "主体先观察目标，再进行接触、发力或操作，画面展示状态变化和明确结果",
  framing: "使用主体清楚、空间关系可读的景别与构图，不用杂乱背景抢夺注意力",
  camera: "单次核心运镜不超过5秒；主体动作先发生，摄影机随后跟随",
  lighting: "保持主光方向、色彩关系和角色轮廓连续，变化必须有可见来源",
  sound: "环境底噪持续，接触、脚步、按钮、机械、撞击或材质声音与可见动作同步",
  end_state: "停在构图稳定、信息明确、无花屏且能够自然续接的动作状态",
});

function completePhase(common, override = {}) {
  const phase = {};
  for (const key of H3_GUIDED_TEMPLATE_PHASE_KEYS) {
    phase[key] = String(override[key] || common[key] || BASE_PHASE[key] || "").trim();
  }
  return Object.freeze(phase);
}

function template(config) {
  const common = { ...BASE_PHASE, ...(config.common || {}) };
  const phases = (config.phases || []).map((phase) => completePhase(common, phase));
  while (phases.length < 4) phases.push(completePhase(common));
  const dialogueDefaults = config.id === "music_video_subtitle_official"
    ? {
      ...H3_GUIDED_SAFE_DIALOGUE_DEFAULTS,
      dialogue: "无角色对白无旁白（歌曲人声仅来自唯一Master Audio和锁定歌词）",
      allow_music_vocals: "true",
    }
    : { ...H3_GUIDED_SAFE_DIALOGUE_DEFAULTS, allow_music_vocals: "false" };
  const lead = H3_GUIDED_TEMPLATE_LEADS[config.id] || {
    label: "核心内容", title: `${config.name || "当前模板"}的核心内容`,
    placeholder: `请填写${config.name || "当前模板"}真正要发生的主体、目标、动作和结果。`, options: [],
  };
  const directing = H3_GUIDED_DIRECTING_PROFILES[config.id] || H3_GUIDED_DIRECTING_FALLBACK;
  return Object.freeze({
    id: config.id,
    group: config.group,
    name: config.name,
    description: config.description,
    sourceSkill: String(config.sourceSkill || "").trim(),
    forceDuration: String(config.forceDuration || "").trim(),
    forceAspect: String(config.forceAspect || "").trim(),
    durationOptions: Object.freeze((config.durationOptions || []).map((item) => String(item || "").trim()).filter(Boolean)),
    strictDurationOptions: Boolean(config.strictDurationOptions),
    lead: Object.freeze({
      label: String(lead.label || "核心内容"),
      title: String(lead.title || `${config.name || "当前模板"}的核心内容`),
      placeholder: String(lead.placeholder || "填写主体、目标、动作和结果"),
      options: Object.freeze((lead.options || []).map((item) => String(item || "").trim()).filter(Boolean)),
    }),
    directing,
    defaults: Object.freeze({ ...config.defaults, ...dialogueDefaults }),
    phases: Object.freeze(phases),
  });
}

