/* “故事节拍”和“镜头调度”必须属于当前模板，而不是所有模板共用一组
   “推拉摇移”。每套配置同时提供可见候选和内部镜头语法：候选写入提示词，
   grammar 负责把约 15 秒 Director 段拆成可执行的内部镜头。 */
function directingProfile({ storyTitle, storyOptions, shotTitle, shotOptions, mode = "cuts", shotCount = 0, grammar }) {
  const stories = (storyOptions || []).map((item) => String(item || "").trim()).filter(Boolean);
  const shots = (shotOptions || []).map((item) => String(item || "").trim()).filter(Boolean);
  const shotGrammar = (grammar || []).map((item) => Object.freeze({
    role: String(item.role || item[0] || "推进当前动作"),
    framing: String(item.framing || item[1] || "主体、目标和空间关系清楚"),
    camera: String(item.camera || item[2] || "主体动作先发生，摄影机随后响应"),
    transition: String(item.transition || item[3] || "动作结果直接交给下一镜"),
  }));
  return Object.freeze({
    story: Object.freeze({
      label: "故事节拍", title: storyTitle, placeholder: `例如 ${stories[0] || "目标→阻碍→行动→结果"}`,
      defaultValue: stories[0] || "目标→阻碍→行动→结果", options: Object.freeze(stories),
    }),
    shots: Object.freeze({
      label: "镜头调度", title: shotTitle, placeholder: `例如 ${shots[0] || "建立镜头→动作镜头→结果镜头"}`,
      defaultValue: shots[0] || "建立镜头→动作镜头→结果镜头", options: Object.freeze(shots),
    }),
    mode, shotCount: Math.max(2, Number(shotCount) || shotGrammar.length), grammar: Object.freeze(shotGrammar),
  });
}

