const guidedField = (title, placeholder, options = [], extra = {}) => Object.freeze({
  title, placeholder, options: Object.freeze(options), catalog: null, ...extra,
});

const guidedUi = (steps, fields = {}) => Object.freeze({
  steps: Object.freeze(steps),
  fields: Object.freeze(fields),
});

