/* 精简向导只收集会真正改变画面的创作事实。故事路线继续由模板自动规划，
   但“镜头语言”必须显式交给用户选择：30套模板各自使用自己的候选，选择后
   会改变绝对时间、镜头职责、景别、机位与摄影机运动，而不是只显示一行标签。 */
