function h3SimplifiedUi(templateId) {
  const detailed = H3_GUIDED_TEMPLATE_UI_DETAILED[String(templateId || "")];
  if (!detailed) return null;
  const selected = getH3GuidedTemplate(templateId);
  const universalFields = {
    duration: guidedField("成片时长", "选择总时长；固定时长模板也会明确显示，便于知道每个镜头有多少秒。",
      selected?.forceDuration ? [selected.forceDuration] : (selected?.durationOptions || ["15秒", "30秒"])),
    aspect: guidedField("画幅比例", "选择最终构图比例；它会改变人物、地标、入口和文字安全区的位置。",
      selected?.forceAspect ? [selected.forceAspect] : ["横屏16:9", "竖屏9:16", "方形1:1", "电影宽银幕21:9"]),
    final_state: h3GuidedFinalStateField(templateId),
    continuity: guidedField("跨镜头连续性",
      "确认哪些身份、位置、朝向、道具状态、动作进度和光位必须从上一镜继承到下一镜。",
      [selected?.defaults?.continuity || "主体身份、位置、朝向、道具和前一镜结果跨镜连续"]),
    constraint: guidedField("当前模板禁止项",
      "只禁止这类视频最容易生成错的内容，防止角色、物件、文字、特效或其它模板语法串入。",
      [selected?.defaults?.constraint || "不新增未建立的角色、道具、地点、文字、Logo或水印"]),
  };
  const fields = { ...universalFields, ...(detailed.fields || {}) };
  const available = new Set([...detailed.steps, "duration", "aspect", "final_state", "continuity", "constraint"]);
  const requested = [...(H3_GUIDED_SIMPLIFIED_STEP_KEYS[String(templateId || "")] || detailed.steps)];
  /* 首框架试点明确声明自己的完整步骤。产品颜色、数量连续、画幅和禁止项由
     产品广告编译器根据实际产品与素材策略自动生成，不再接统一模板尾巴。 */
  if (String(templateId || "") === "minimalist_product_ad_official") {
    return guidedUi(requested.filter((key) => available.has(key)), fields);
  }
  if (!requested.includes("duration")) {
    const firstCreativeIndex = Math.min(1, requested.length);
    requested.splice(firstCreativeIndex, 0, "duration");
  }
  /* 所有创作模板都显示自己 directing profile 中的镜头候选。放在时长之后，
     用户先确定主题与总时长，再直接看到“几秒拍什么、怎样拍”的可点击路线。 */
  if (available.has("shot_language") && !requested.includes("shot_language")) {
    const durationIndex = requested.indexOf("duration");
    requested.splice(durationIndex >= 0 ? durationIndex + 1 : 1, 0, "shot_language");
  }
  /* 2.24.10 的内联搭建器必须让用户真正知道成片比例、现场声音和配乐策略。
     这些项目不再藏在模板默认值里：有对应字段的模板统一加入流程，但纸拼贴
     等已经用 audio_policy 合并声音策略的模板不会重复追加近义步骤。 */
  if (available.has("aspect") && !requested.includes("aspect")) {
    const durationIndex = requested.indexOf("duration");
    requested.splice(durationIndex >= 0 ? durationIndex + 1 : 1, 0, "aspect");
  }
  /* 空间布局、连续性和禁止项会直接决定模型是否瞬移、换装、越轴或串入其它
     模板内容，因此也必须让用户看到并确认；不再只放在隐藏默认值里。 */
  for (const key of ["scene_layout", "sound", "music", "final_state", "continuity", "onscreen_text", "constraint"]) {
    if (available.has(key) && !requested.includes(key)) requested.push(key);
  }
  const steps = requested.filter((key) => available.has(key));
  return guidedUi(steps, fields);
}

/* 只有选择了精确对白/旁白，才把语言、逐字台词和表演方向展开到蓝色流程。
   无对白是默认安全路径，不能仍显示三个不可用输入框把用户步骤数虚增。 */
const H3_GUIDED_SPOKEN_DETAIL_KEYS = new Set(["dialogue_language", "dialogue_script", "voice_direction"]);

export function getH3GuidedVisibleTemplateUi(templateId, fields = {}) {
  const ui = h3SimplifiedUi(templateId);
  if (!ui) return null;
  const speechEnabled = /精确(?:角色对白|旁白)|角色对白\s*\+\s*旁白/.test(String(fields.dialogue || ""))
    && !/(?:无对白|无台词|仅环境声|纯环境声)/.test(String(fields.dialogue || ""));
  const steps = ui.steps.filter((key) => speechEnabled || !H3_GUIDED_SPOKEN_DETAIL_KEYS.has(key));
  return guidedUi(steps, ui.fields);
}

export function getH3GuidedTemplateUi(templateId) {
  return h3SimplifiedUi(templateId);
}

