const H3_INLINE_GUIDE_LABELS = Object.freeze({
  product_material: "材质证据", product_action: "核心产品动作", product_result: "可见结果证明",
  source_assets: "参考素材", ad_style: "广告场景", text_mode: "画面文字", ad_copy_text: "唯一文案",
  scene_layout: "空间与入口布局", props: "道具或装备", shot_language: "镜头语言",
  final_state: "最后帧或续接状态",
  dialogue_script: "精确台词", source_copy: "原始观点", audio_policy: "拼贴声音策略",
});

function h3InlineGuidePurpose(template, key, spec = {}) {
  const explicit = H3_INLINE_GUIDE_META[key];
  if (explicit) return explicit[1];
  const label = String(spec.label || spec.title || H3_INLINE_GUIDE_LABELS[key] || key);
  const family = h3GuidedExecutionFamily(template?.id || "");
  const familyText = {
    product: "产品身份、真实操作和最后结果",
    game_ui: "玩家位置、界面状态和确认反馈",
    game_action: "角色、装备、入口动作和关卡结果",
    pixel: "像素角色、卷轴方向和关卡状态",
    papercraft: "知识对象、纸艺机关和学习结果",
    collage: "纸片隐喻、组装动作和观点结论",
    music: "主音轨、节拍、歌词和空间文字",
    handdrawn: "同一实拍空间、手绘实体和连续追拍",
    action: "身体动作、接触、受力和落点",
    narrative: "人物目标、因果行动和关系结果",
  }[family] || "主体、动作和结果";
  return `这一项会改变${familyText}中的“${label}”，并写入后续绝对时间镜头表。`;
}

function h3InlineGuideOptions(template, key, spec, fields, topic) {
  const packageValues = getH3GuidedCreativePackages(template.id, fields, topic)
    .map((item) => item && item.fields && item.fields[key]).filter(Boolean);
  let options = [];
  if (key === "shot_language") options = template.id === "minimalist_product_ad_official"
    ? h3GuidedProductShotOptions(fields) : (template.directing?.shots?.options || []);
  else if (key === "narrative_spine" && template.id === "minimalist_product_ad_official") {
    options = h3GuidedProductNarrativeOptions(fields);
  }
  else if (key === "duration") options = template.forceDuration
    ? [template.forceDuration] : (template.durationOptions?.length ? template.durationOptions : ["15秒", "30秒", "60秒"]);
  else if (key === "aspect") options = template.forceAspect
    ? [template.forceAspect] : ["横屏16:9", "竖屏9:16", "方形1:1", "电影宽银幕21:9"];
  else options = getH3GuidedFieldSuggestions(template.id, key, fields, spec.options || []);
  const common = {
    dialogue: ["无对白无旁白（纯环境声和动作音效，最稳）", "精确角色对白（必须填写时间、说话人和台词原文）", "精确旁白（必须填写时间、旁白者和原文）"],
    dialogue_language: ["普通话（简体中文）", "英文"],
    dialogue_script: ["0.000–2.000秒｜角色名｜准确台词原文", "3.000–5.000秒｜旁白｜准确旁白原文"],
    voice_direction: ["自然语速、口齿清楚、逐字照读；动作音效和配乐在人声下压低"],
    source_assets: ["无参考素材·纯文生视频，不引用图片、Logo、包装或外部品牌资产"],
    sound: [template.defaults?.sound || "真实环境底噪与可见动作音效逐项同步"],
    music: [template.defaults?.music || "无背景音乐，只保留环境声和同步动作音效"],
    onscreen_text: [template.defaults?.onscreen_text || "无屏幕文字和字幕"],
    style: [template.defaults?.style || template.name],
    constraint: [template.defaults?.constraint || "不新增未建立的角色、道具、地点、文字、Logo或水印"],
    continuity: [template.defaults?.continuity || "主体身份、位置、朝向、道具和前一镜结果跨镜连续"],
    final_state: [fields.product_result || template.defaults?.final_state
      || "当前核心动作完成，主体、道具、空间关系和可见结果清楚稳定"],
    aspect: [template.forceAspect || template.defaults?.aspect || "横屏16:9"],
  }[key] || [];
  const current = String(fields[key] || template.defaults?.[key] || "").trim();
  const candidates = [current, ...packageValues, ...options, ...common].filter(Boolean);
  if (key === "product_name") {
    const context = `${topic || ""} ${fields.product_name || ""}`;
    let productCandidates = candidates.filter(isValidH3ProductNameCandidate);
    if (/苹果|apple/i.test(context)) productCandidates = productCandidates.filter((value) => /苹果|apple/i.test(value));
    else if (/手机|电话|phone|折叠屏/i.test(context)) productCandidates = productCandidates.filter((value) => /手机|电话|phone|折叠屏/i.test(value));
    else if (/耳机|音箱|音响|speaker|headphone|耳塞/i.test(context)) productCandidates = productCandidates.filter((value) => /耳机|音箱|音响|speaker|headphone|耳塞/i.test(value));
    return h3GuidedUnique(productCandidates, 7);
  }
  return h3GuidedUnique(candidates, 7);
}

/**
 * 为主分镜输入框生成“每次只决定一项”的内联搭建计划。这里不会应用整套创作
 * package，也不会生成官方 Base；package 只作为当前字段的具体候选来源。
 */
export function buildH3InlineGuidePlan(templateId, fields = {}, options = {}) {
  const selected = getH3GuidedTemplate(templateId);
  if (!selected) return Object.freeze({ templateId: "", templateName: "", steps: Object.freeze([]) });
  const ui = getH3GuidedVisibleTemplateUi(selected.id, fields) || guidedUi([], {});
  const topic = String(options.topic || fields.creative_topic || fields.content || fields.product_name
    || fields.story_premise || fields.knowledge_topic || fields.brand_name || "").trim();
  const steps = [];
  for (const key of ui.steps) {
    if (key === "ad_copy_text" && /(?:无文字|无文案)/.test(String(fields.text_mode || ""))) continue;
    let spec = { ...(ui.fields?.[key] || {}) };
    if (key === "content" && selected.lead) spec = { ...spec, ...selected.lead, required: true };
    if (key === "shot_language") spec = {
      ...spec, title: selected.directing?.shots?.title || "选择镜头语言",
      placeholder: "选择一条作为草稿；它会改变镜头职责、绝对时间、景别、机位和运镜。",
    };
    const meta = H3_INLINE_GUIDE_META[key];
    const label = String(spec.label || H3_INLINE_GUIDE_LABELS[key] || meta?.[0] || spec.title || key);
    const purpose = h3InlineGuidePurpose(selected, key, spec);
    steps.push(Object.freeze({
      key, label, title: String(spec.title || meta?.[0] || label), purpose,
      prompt: String(spec.placeholder || `请选择一条“${label}”候选作为草稿，也可以直接在主输入框中修改。`),
      required: true, multiple: Boolean(spec.multiple),
      options: Object.freeze(h3InlineGuideOptions(selected, key, spec, fields, topic)),
    }));
  }
  return Object.freeze({
    templateId: selected.id, templateName: selected.name, topic,
    steps: Object.freeze(steps),
  });
}

/** 返回当前模板真正显示给用户的字段名，供可视化流程和本地校验共用。 */
export function getH3GuidedTemplateFieldLabels(templateId) {
  const ui = getH3GuidedTemplateUi(templateId);
  if (!ui) return [];
  return ui.steps.map((key) => {
    const spec = ui.fields && ui.fields[key];
    return Object.freeze({ key, label: String(spec && (spec.label || spec.title) || key) });
  });
}

