export function getH3GuidedCreativePackages(templateId, fields = {}, liveValue = "") {
  const topic = h3GuidedCleanCreativeTopic(liveValue || fields.creative_topic || fields.content
    || fields.product_name || fields.story_premise || fields.knowledge_topic || fields.brand_name || "");
  return Object.freeze(h3SpecialCreativePackages(String(templateId || ""), topic).slice(0, 5));
}

export function applyH3GuidedCreativePackage(templateId, currentFields = {}, packageOrId = null) {
  const packages = getH3GuidedCreativePackages(templateId, currentFields, currentFields.creative_topic || "");
  const chosen = typeof packageOrId === "object" && packageOrId
    ? packageOrId : packages.find((item) => item.id === String(packageOrId || ""));
  if (!chosen) return { fields: { ...currentFields }, package: null, changedKeys: [] };
  const previousAuto = currentFields.guided_creative_auto_values && typeof currentFields.guided_creative_auto_values === "object"
    ? currentFields.guided_creative_auto_values : {};
  const fields = { ...currentFields };
  const nextAuto = {};
  const changedKeys = [];
  for (const [key, value] of Object.entries(chosen.fields || {})) {
    const current = String(fields[key] || "").trim();
    const oldAuto = String(previousAuto[key] || "").trim();
    if (!current || current === oldAuto) {
      fields[key] = value;
      nextAuto[key] = value;
      changedKeys.push(key);
    }
  }
  for (const [key, value] of Object.entries(previousAuto)) {
    if (!Object.hasOwn(nextAuto, key) && String(fields[key] || "").trim() === String(value || "").trim()) nextAuto[key] = value;
  }
  fields.creative_package_id = chosen.id;
  fields.creative_package_label = chosen.label;
  fields.guided_creative_auto_values = nextAuto;
  return { fields, package: chosen, changedKeys };
}

export function validateH3GuidedConcreteFields(templateId, fields = {}) {
  const issues = [];
  const labels = {
    content: "具体剧情", story_premise: "故事任务", characters: "人物与关系", appearance: "人物造型",
    scene: "主场景", scene_layout: "固定布局", props: "道具及用途", live_space: "实拍地点",
    contact_method: "真实接触", drawn_entity: "手绘主体", transform_chain: "变形链", chase_route: "追逐路线",
    product_name: "产品", product_action: "产品操作", product_result: "产品结果",
  };
  const concreteKeys = new Set(["content", "story_premise", "characters", "appearance", "scene", "scene_layout", "props",
    "live_space", "contact_method", "drawn_entity", "transform_chain", "chase_route", "product_name", "product_action", "product_result"]);
  const patterns = [
    /主角与一名关系角色|主角\s*\+\s*一名关系角色|只保留完成.+所必需|只使用一个能直接支持|围绕.+锁定角色轮廓|只保留直接参与.+1\s*[–—-]\s*2件/i,
    /第一形态|第二形态|第三形态|第一种平面小物件|已有小物件|某个(?:场景|物件|道具|动作)|金属\s*[\/或]\s*玻璃表面|按钮或轻微机关/i,
    /当前主体|当前目标|相关能力|准确台词|角色名|说话人|待填写|待确认(?:人物|场景|道具|剧情)/i,
  ];
  for (const [key, raw] of Object.entries(fields || {})) {
    if (!concreteKeys.has(key)) continue;
    const value = String(raw || "").trim();
    const hit = patterns.find((pattern) => pattern.test(value));
    if (hit) issues.push({ severity: "error", code: "abstract_guided_field", key,
      message: `“${labels[key] || key}”仍是抽象框架，请点选一条具体创作方案或改成具体人物、地点、物件和动作。` });
  }
  if (/handdrawn_live/.test(String(templateId || ""))) {
    for (const key of ["live_space", "contact_method", "drawn_entity", "transform_chain", "chase_route"]) {
      if (!String(fields[key] || "").trim()) issues.push({ severity: "error", code: "missing_handdrawn_detail", key,
        message: `手绘实拍需要具体填写“${labels[key] || key}”，不能用形态编号代替。` });
    }
  }
  return Object.freeze({ ok: !issues.some((item) => item.severity === "error"), issues: Object.freeze(issues) });
}

export function getH3GuidedDialogueSuggestions(templateId, fields = {}, segmentIndex = 0) {
  const content = String(fields.content || fields.story_premise || "");
  const names = String(fields.characters || "").split(/[、,，；;\n]+/).map((item) => item.split(/[：:]/)[0].trim())
    .filter((item) => item && item.length <= 8 && !/只有|主角|角色|人物/.test(item));
  if (/music_video/.test(String(templateId || ""))) return [];
  if (/brand_promo/.test(String(templateId || "")) && String(fields.verified_claim || "").trim()) {
    return [{ speaker: "旁白", text: String(fields.verified_claim).replace(/^只(?:展示|证明)/, "").slice(0, 36) }];
  }
  if (/papercraft/.test(String(templateId || ""))) {
    const topic = String(fields.knowledge_topic || "这个过程").slice(0, 24);
    return [{ speaker: "旁白", text: segmentIndex ? `现在可以看到${topic}的结果。` : `先看${topic}从哪里开始。` }];
  }
  if (/死人|来电|手机/.test(content) && names.length >= 2) return segmentIndex
    ? [{ speaker: names[0], text: "钥匙一直在我这里。" }, { speaker: names[1], text: "那就由你打开。" }]
    : [{ speaker: names[0], text: "手机是不是在你那里？" }, { speaker: names[1], text: "先看清证据。" }];
  if (names.length) return [{ speaker: names[0], text: segmentIndex ? "这次按证据做决定。" : "先把眼前的结果确认清楚。" }];
  return [];
}

export function getH3GuidedTopicSuggestions(templateId, fields = {}, liveValue = "") {
  const merged = liveValue ? { ...fields, content: liveValue } : fields;
  const topic = h3GuidedTopicAssist(merged);
  const subject = String(liveValue || h3GuidedTopicText(merged) || "当前主题").trim();
  const topicOptions = topic && h3GuidedUsesProductTopic(templateId) ? topic.summary : [];
  const packages = getH3GuidedCreativePackages(templateId, fields, subject).map((item) => item.label);
  return h3GuidedUnique([...packages, ...topicOptions], 8);
}

